// 三个类、五个对象
// 类：StartupBust（游戏）/ Startup（公司）/ GameHelper（助手）
// 对象：1 个 StartupBust + 3 个 Startup + 1 个 GameHelper
// 四个 ArrayList：StartupBust 装 3 公司；每公司装 3 个位置格子

// StartupBust 四份工作（拆成小方法，粒度更细）：
// setUpGame()      设置：造公司、起名、放位置
// startPlaying()   玩：循环读输入直到公司全死
// checkUserGuess() 检查一次猜测
// finishGame()     结束：打印评级

// setUpGame() prep
// CREATE 3 Startups, SET names, ADD to startups
// REPEAT each Startup: helper.placeStartup(3) → setLocationCells

// startPlaying() prep
// WHILE any Startups exist: getUserInput → checkUserGuess

// checkUserGuess(String) prep
// numOfGuesses++; result="miss"
// FOR each Startup: result=checkYourself(guess)
//   IF kill: REMOVE Startup from list
// DISPLAY result

// finishGame() prep
// DISPLAY 结束消息；猜测少→祝贺，多→嘲讽

import java.util.ArrayList;
public class StartupBust {
  private GameHelper helper = new GameHelper();
  private ArrayList<Startup> startups = new ArrayList<Startup>();
  private int numOfGuesses = 0;
  private void setUpGame() {
    Startup one = new Startup(); one.setName("poniez");
    Startup two = new Startup(); two.setName("hacqi");
    Startup three = new Startup(); three.setName("cabista");
    startups.add(one); startups.add(two); startups.add(three);
    System.out.println("Your goal is to sink three Startups.");
    // ...说明...
    for (Startup startup : startups) {          // 增强 for 遍历 ArrayList
      ArrayList<String> newLocation = helper.placeStartup(3);
      startup.setLocationCells(newLocation);
    }
  }
  private void startPlaying() {
    while (!startups.isEmpty()) {               // 列表不空就继续
      String userGuess = helper.getUserInput("Enter a guess");
      checkUserGuess(userGuess);
    }
    finishGame();
  }

private void checkUserGuess(String userGuess) {
  numOfGuesses++;
  String result = "miss";
  for (Startup startupToTest : startups) {
    result = startupToTest.checkYourself(userGuess);
    if (result.equals("hit")) break;
    if (result.equals("kill")) {
      startups.remove(startupToTest);  // 遍历中删除：注意 fail-fast 陷阱
      break;
    }
  }
  System.out.println(result);
}
private void finishGame() {
  System.out.println("All Startups are dead! ...");
  if (numOfGuesses <= 18) { /* 表扬 */ }
  else { /* 嘲讽 */ }
}
public static void main(String[] args) {
  StartupBust game = new StartupBust();
  game.setUpGame(); game.startPlaying();   // main 只有三行！
}

