private void setUpMidi() {
  try {
    sequencer = MidiSystem.getSequencer();       // 工厂方法拿音序器（接口 -> 具体实现）
    sequencer.open();                            // 打开设备，准备播放
    sequence = new Sequence(Sequence.PPQ, 4);    // PPQ 分辨率，每四分音符 4 tick
    track = sequence.createTrack();              // 建一条轨道
    sequencer.setTempoInBPM(120);                // 每分钟 120 拍
  } catch (Exception e) {
    e.printStackTrace();                         // 受检异常必须处理
  }
}

private void changeTempo(float tempoMultiplier) {
  float tempoFactor = sequencer.getTempoFactor();          // 读当前倍率
  sequencer.setTempoFactor(tempoFactor * tempoMultiplier);  // 读-改-写：累积调整
}
// 默认 factor=1.0；Tempo Up 传 1.03f（快 3%），Down 传 0.97f（慢 3%）。
// factor 是音序器级属性，循环各轮自动保持新速度。

private void buildTrackAndStart() {
  int[] trackList;
  sequence.deleteTrack(track);              // 丢掉旧轨道
  track = sequence.createTrack();           // 建全新轨道，保证每次干净

  for (int i = 0; i < 16; i++) {            // 外层：16 行 = 16 个乐器
    trackList = new int[16];                // 这个乐器横跨 16 拍的发声清单
    int key = instruments[i];               // 该乐器的 MIDI 音符编号
    for (int j = 0; j < 16; j++) {          // 内层：16 拍 = 16 列
      JCheckBox jc = checkboxList.get(j + 16 * i);  // 行优先下标 = 行号*列数+列号
      trackList[j] = jc.isSelected() ? key : 0;     // 勾了放 key，没勾放 0（哨兵）
    }
    // 下半节：makeTracks(trackList) 把这一行变成 MIDI 事件……
  }
  // ……
}

// j + 16*i 详解：GridLayout(16,16) 与 add 顺序都是行优先，
// 第 i 行第 j 列 -> 一维下标 i*16+j。第 0 行 0~15，第 1 行 16~31……

private void buildTrackAndStart() {
  int[] trackList;
  sequence.deleteTrack(track);              // 丢掉旧轨道
  track = sequence.createTrack();           // 建全新轨道

  for (int i = 0; i < 16; i++) {            // 16 行 = 16 个乐器
    trackList = new int[16];
    int key = instruments[i];
    for (int j = 0; j < 16; j++) {          // 16 拍
      JCheckBox jc = checkboxList.get(j + 16 * i);
      trackList[j] = jc.isSelected() ? key : 0;
    }
    makeTracks(trackList);                  // 这一行 -> MIDI 事件
    track.add(makeEvent(CONTROL_CHANGE, 1, 127, 0, 16)); // 第 16 拍占位，保证循环走满 16 拍
  }
  track.add(makeEvent(PROGRAM_CHANGE, 9, 1, 0, 15));     // 切到正确的鼓组音色
  try {
    sequencer.setSequence(sequence);
    sequencer.setLoopCount(sequencer.LOOP_CONTINUOUSLY);  // 无限循环
    sequencer.setTempoInBPM(120);
    sequencer.start();                                   // 开播！
  } catch (Exception e) {
    e.printStackTrace();
  }
}

private void makeTracks(int[] list) {
  for (int i = 0; i < 16; i++) {
    int key = list[i];
    if (key != 0) {                          // 0 = 这一拍不响
      track.add(makeEvent(NOTE_ON, 9, key, 100, i));      // 第 i 拍开始
      track.add(makeEvent(NOTE_OFF, 9, key, 100, i + 1)); // 下一拍停止，持续一拍
    }
  }
}
